use strict;
use warnings;
use File::Find;
use File::Slurp;

my $root = '/bench/repo';
my $internal = "$root/internal";

# Parse declarations in internal/ non-test files
my @decls;  # { name, qual, path, line, is_method, recv, pkg }

sub parse_file {
    my ($path) = @_;
    return if $path =~ /_test\.go$/;
    my $rel = $path; $rel =~ s/^\Q$root\E\/?//;
    my $content = read_file($path);
    my ($pkg) = $content =~ /^package\s+(\w+)/m;
    return unless $pkg;

    my @lines = split /\n/, $content;
    for my $i (0..$#lines) {
        my $line = $lines[$i];
        next unless $line =~ /^\s*func\s+/;
        if ($line =~ /^\s*func\s+\(([^)]+)\)\s+(\w+)\s*\(/) {
            my ($recv, $name) = ($1, $2);
            my ($recv_type) = $recv =~ /(\*?\w+)\s*$/;
            $recv_type =~ s/^\*//;
            push @decls, {
                name => $name,
                qual => "$recv_type.$name",
                path => $rel,
                line => $i+1,
                is_method => 1,
                recv => $recv_type,
                pkg => $pkg,
            };
        } elsif ($line =~ /^\s*func\s+(\w+)\s*\(/) {
            my $name = $1;
            push @decls, {
                name => $name,
                qual => "$pkg.$name",
                path => $rel,
                line => $i+1,
                is_method => 0,
                pkg => $pkg,
            };
        }
    }
}

find({ wanted => sub { parse_file($File::Find::name) if /\.go$/ && -f $_ && index($File::Find::name, '/internal/') >= 0 }, no_chdir => 1 }, $internal);

# Build package alias map from imports - simplified: just count by import path ending
# Collect all non-test go file contents for searching
my @files;
find({ wanted => sub {
    return unless /\.go$/;
    return if /_test\.go$/;
    return if /proto\/gen/;
    push @files, $File::Find::name;
}, no_chdir => 1 }, $root);

# For each decl, count approximate call sites
my %fanin;

for my $d (@decls) {
    my $name = $d->{name};
    my $count = 0;
    my @patterns;

    if ($d->{is_method}) {
        # .MethodName( but not declaration line
        push @patterns, qr/\.$name\s*\(/;
    } else {
        # For exported: package.Name or bare Name in other contexts
        if ($name =~ /^[A-Z]/) {
            # import alias patterns - count \bName\( and \.\w*Name\( and pkg paths
            my $pkg = $d->{pkg};
            push @patterns, qr/\b$name\s*\(/;
            # also count explicit import path style like markdown.New
            push @patterns, qr/\.$name\s*\(/;
        } else {
            # unexported - only count within same package files... hard. skip or same dir
            push @patterns, qr/\b$name\s*\(/;
        }
    }

    for my $f (@files) {
        my $content = read_file($f);
        my $rel = $f; $rel =~ s/^\Q$root\E\/?//;
        my @lines = split /\n/, $content;
        for my $i (0..$#lines) {
            my $line = $lines[$i];
            next if $rel eq $d->{path} && ($i+1) == $d->{line}; # skip own decl
            next if $line =~ /^\s*func\s+/; # skip declarations
            for my $p (@patterns) {
                if ($line =~ /$p/) {
                    # For unexported funcs, only count if same package
                    if ($name =~ /^[a-z]/ && $d->{is_method} == 0) {
                        my ($fpkg) = $content =~ /^package\s+(\w+)/m;
                        next unless $fpkg && $fpkg eq $d->{pkg};
                    }
                    $count++;
                    last;
                }
            }
        }
    }
    $fanin{"$d->{qual} — $d->{path}:$d->{line}"} = $count;
}

my @sorted = sort { $fanin{$b} <=> $fanin{$a} } keys %fanin;
print "Top 25 by approximate fan-in:\n";
for my $i (0..24) {
    last unless defined $sorted[$i];
    print "$fanin{$sorted[$i]}\t$sorted[$i]\n";
}
print "\nTotal decls: ", scalar(@decls), "\n";
PERL

