use strict;
use warnings;

my $root = '/bench/repo';
my @internal_files = map { chomp; $_ } `cat /tmp/internal_files.txt`;
my @all_files = map { chomp; $_ } `cat /tmp/all_files.txt`;

sub read_file {
    my ($path) = @_;
    open my $fh, '<', $path or return '';
    local $/; my $c = <$fh>; close $fh;
    return $c;
}

my @decls;
for my $path (@internal_files) {
    my $rel = $path; $rel =~ s/^\Q$root\E\/?//;
    my $content = read_file($path);
    my ($pkg) = $content =~ /^package\s+(\w+)/m;
    next unless $pkg;
    my @lines = split /\n/, $content;
    for my $i (0..$#lines) {
        my $line = $lines[$i];
        next unless $line =~ /^\s*func\s+/;
        if ($line =~ /^\s*func\s+\(([^)]+)\)\s+(\w+)\s*\(/) {
            my ($recv, $name) = ($1, $2);
            my ($recv_type) = $recv =~ /(\*?\w+)\s*$/;
            $recv_type =~ s/^\*//;
            push @decls, { name=>$name, qual=>"$recv_type.$name", path=>$rel, line=>$i+1, is_method=>1, pkg=>$pkg };
        } elsif ($line =~ /^\s*func\s+(\w+)\s*\(/) {
            my $name = $1;
            push @decls, { name=>$name, qual=>"$pkg.$name", path=>$rel, line=>$i+1, is_method=>0, pkg=>$pkg };
        }
    }
}

# Preload all file contents
my %file_content;
my %file_pkg;
for my $f (@all_files) {
    my $c = read_file($f);
    $file_content{$f} = $c;
    my ($pkg) = $c =~ /^package\s+(\w+)/m;
    $file_pkg{$f} = $pkg // '';
}

my %fanin;
for my $d (@decls) {
    my $name = $d->{name};
    my $count = 0;
    for my $f (@all_files) {
        my $rel = $f; $rel =~ s/^\Q$root\E\/?//;
        my @lines = split /\n/, $file_content{$f};
        for my $i (0..$#lines) {
            my $line = $lines[$i];
            next if $rel eq $d->{path} && ($i+1) == $d->{line};
            next if $line =~ /^\s*func\s+/;
            my $matched = 0;
            if ($d->{is_method}) {
                $matched = 1 if $line =~ /\.$name\s*\(/;
            } else {
                if ($name =~ /^[A-Z]/) {
                    $matched = 1 if $line =~ /\b$name\s*\(/ || $line =~ /\.$name\s*\(/;
                } else {
                    next unless $file_pkg{$f} eq $d->{pkg};
                    $matched = 1 if $line =~ /\b$name\s*\(/;
                }
            }
            if ($matched) { $count++; last; } # count once per line... actually count each matching line
        }
    }
    # recount properly - count matching lines not once per file
    $count = 0;
    for my $f (@all_files) {
        my $rel = $f; $rel =~ s/^\Q$root\E\/?//;
        my @lines = split /\n/, $file_content{$f};
        for my $i (0..$#lines) {
            my $line = $lines[$i];
            next if $rel eq $d->{path} && ($i+1) == $d->{line};
            next if $line =~ /^\s*func\s+/;
            if ($d->{is_method}) {
                $count++ if $line =~ /\.$name\s*\(/;
            } else {
                if ($name =~ /^[A-Z]/) {
                    $count++ if $line =~ /\b$name\s*\(/ || $line =~ /\.$name\s*\(/;
                } else {
                    next unless $file_pkg{$f} eq $d->{pkg};
                    $count++ if $line =~ /\b$name\s*\(/;
                }
            }
        }
    }
    $fanin{"$d->{qual}|$d->{path}:$d->{line}"} = $count;
}

my @sorted = sort { $fanin{$b} <=> $fanin{$a} } keys %fanin;
print "Top 30:\n";
for my $i (0..29) {
    last unless defined $sorted[$i];
    my ($sym, $loc) = split /\|/, $sorted[$i], 2;
    print "$fanin{$sorted[$i]}\t$sym — $loc\n";
}
