# Full scan: all unexported funcs in internal, count \bname\s*( or .name\s*( in internal tree
perl - <<'PERL'
use strict; use warnings;
my $root='/bench/repo';
my @ifiles = map { chomp } `cat /tmp/internal_files.txt`;
sub rf { open my $f,'<',$_[0] or return ''; local $/; <$f> }

my @decls;
for my $path (@ifiles) {
  my $rel=$path; $rel=~s/^\Q$root\E\/?//;
  my ($dir)=$rel=~/^(.*)\/[^\/]+$/;
  my $c=rf($path);
  for my $line (split/\n/,$c) {
    next unless $line=~/^\s*func\s+/;
    if ($line=~/^\s*func\s+\(([^)]+)\)\s+(\w+)\s*\(/) {
      my ($r,$n)=($1,$2); my ($rt)=$r=~/(\w+)\s*$/;
      push @decls, {n=>$n, q=>"$rt.$n", p=>$rel, dir=>$dir, meth=>1};
    } elsif ($line=~/^\s*func\s+(\w+)\s*\(/ && $1=~/^[a-z]/) {
      push @decls, {n=>$1, q=>"$1", p=>$rel, dir=>$dir, meth=>0};
    }
  }
}

my $max=0; my @top;
for my $d (@decls) {
  my $pat = $d->{meth} ? "\\.$d->{n}\\s*\\(" : "\\b$d->{n}\\s*\\(";
  my $cnt=0;
  for my $path (@ifiles) {
    next unless index($path, $d->{dir}) >= 0; # same package subtree
    my $c=rf($path);
    for my $line (split/\n/,$c) {
      next if $line=~/^\s*func\s+/;
      $cnt++ if $line=~/ $pat /x || $line=~/$pat/;
    }
  }
  push @top, [$cnt, "$d->{q} — $d->{p}"] if $cnt > 0;
}
@top = sort { $b->[0] <=> $a->[0] } @top;
for (0..14) { print "$top[$_][0]\t$top[$_][1]\n" if $top[$_]; }
PERL

